72		putChunk(t, h, "dev-2", "att-2", 1, []byte("ontent"))
73		if w, body := completeAttachment(t, h, "dev-2", "att-2"); w.Code != http.StatusOK || body["complete"] != true {
74			t.Fatalf("complete att-2 = %d %v", w.Code, body)
75		}
76		mustCreateAttachment(t, h, "dev-1", "att-3", []byte("data"), 2)
77		setAccess(t, h, "dev-2", "att-2", "dev-1", "grant")
78	
79		w, items := getAttachmentList(t, h, "/v1/devices/dev-1/attachments")
80		if w.Code != http.StatusOK {
81			t.Fatalf("list = %d body=%s", w.Code, w.Body.String())
82		}
83		if got := listIDs(items); !equalStrings(got, []string{"att-1", "att-2", "att-3"}) {
84			t.Fatalf("list order = %v, want [att-1 att-2 att-3]", got)
85		}
