97		if items[1]["owned"] != false ||
98			items[1]["totalBytes"] != float64(14) ||
99			items[1]["chunkSize"] != float64(8) ||
100			items[1]["sha256"] != sha256Hex([]byte("shared content")) ||
101			items[1]["complete"] != true ||
102			fmt.Sprint(items[1]["receivedChunks"]) != "[0 1]" {
103			t.Fatalf("granted entry = %v", items[1])
104		}
105		// Fresh upload with no chunks yet: an empty (non-null) progress array.
106		if items[2]["owned"] != true || fmt.Sprint(items[2]["receivedChunks"]) != "[]" {
107			t.Fatalf("empty-progress entry = %v", items[2])
108		}
