275	// A deleted attachment vanishes from every listing at once — the creator's
276	// and every granted device's — and re-creating the id lists a brand-new
277	// record at the end of the creation order with its progress back to zero.
278	func TestListAttachmentsDeleteAndRecreate(t *testing.T) {
279		h, _ := newTestHandler(t)
280		registerDevice(t, h, "dev-1")
281		registerDevice(t, h, "dev-2")
