302		_, items = getAttachmentList(t, h, "/v1/devices/dev-1/attachments")
303		if got := listIDs(items); !equalStrings(got, []string{"att-2", "att-1"}) {
304			t.Fatalf("list after recreate = %v, want [att-2 att-1]", got)
