361		mustCreateAttachment(t, h, "dev-2", "att-2", []byte("shared content"), 8)
362		setAccess(t, h, "dev-2", "att-2", "dev-1", "grant")
363	
364		snapshot := func(t *testing.T, h http.Handler) map[string]string {
365			t.Helper()
366			bodies := map[string]string{}
367			for _, url := range []string{
368				"/v1/devices/dev-1/attachments",
369				"/v1/devices/dev-1/attachments?limit=1&offset=0",
370				"/v1/devices/dev-1/attachments?limit=1&offset=1",
371				"/v1/devices/dev-2/attachments",
372			} {
