374				w := serveRecorder(h, r)
375				if w.Code != http.StatusOK {
376					t.Fatalf("GET %s = %d", url, w.Code)
377				}
378				bodies[url] = w.Body.String()
379			}
380			return bodies
381		}
382	
383		before := snapshot(t, h)
384		_ = s.Close()
385	
386		h, s = open(t)
387		defer func() { _ = s.Close() }()
388		after := snapshot(t, h)
389		for url, body := range before {
390			if after[url] != body {
391				t.Fatalf("GET %s after restart = %s, want %s", url, after[url], body)
392			}
