465		h, s := newTestHandler(t)
466	
467		// First change on a new doc, baseCursor 0 -> applied cursor 1.
468		w, body := mergeBody(t, h, "doc", map[string]any{
469			"deviceId": "dev", "baseCursor": 0,
470			"change": map[string]any{"id": "c1", "payload": map[string]any{"a": 1}},
471		})
472		if w.Code != 200 {
473			t.Fatal(w.Body.String())
474		}
475		if body["outcome"] != "applied" || body["cursor"].(float64) != 1 {
476			t.Fatalf("applied = %v", body)
477		}
478	
479		// baseCursor ahead -> 400.
480		w, _ = mergeBody(t, h, "doc", map[string]any{
481			"deviceId": "dev", "baseCursor": 9,
482			"change": map[string]any{"id": "cX", "payload": map[string]any{"z": 1}},
483		})
484		if w.Code != http.StatusBadRequest {
485			t.Fatalf("ahead base = %d", w.Code)
486		}
487	
488		// Same id repost -> idempotent with embedded result.
489		w, body = mergeBody(t, h, "doc", map[string]any{
490			"deviceId": "dev", "baseCursor": 1,
491			"change": map[string]any{"id": "c1", "payload": map[string]any{"a": 1}},
492		})
493		if w.Code != 200 || body["outcome"] != "idempotent" || body["cursor"].(float64) != 1 {
494			t.Fatalf("idempotent = %d %v", w.Code, body)
495		}
496		res := body["result"].(map[string]any)
497		if res["id"] != "c1" || res["created"] != false || res["cursor"].(float64) != 1 {
498			t.Fatalf("embedded result = %v", res)
499		}
500	
501		// Same id, different payload -> 409 carrying the conflicting id in a
502		// structured conflictId field rather than embedded in the message.
503		w, conflictBody := mergeBody(t, h, "doc", map[string]any{
504			"deviceId": "dev", "baseCursor": 1,
505			"change": map[string]any{"id": "c1", "payload": map[string]any{"a": 2}},
506		})
507		if w.Code != http.StatusConflict {
508			t.Fatalf("conflict = %d body=%s", w.Code, w.Body.String())
509		}
510		if conflictBody["conflictId"] != "c1" || conflictBody["error"] == nil {
511			t.Fatalf("merge 409 body = %v, want error and conflictId=c1", conflictBody)
512		}
513	
514		// Seed a second object {"b":2} at cursor 2.
515		w, _ = postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
516			"deviceId": "dev",
517			"changes":  []any{map[string]any{"id": "c2", "payload": map[string]any{"b": 2}}},
518		})
519		if w.Code != 200 {
520			t.Fatal(w.Body.String())
521		}
522	
523		// Stale client at baseCursor 1 posts {"c":3}: disjoint from later {"b":2} -> merged cursor 3.
524		w, body = mergeBody(t, h, "doc", map[string]any{
525			"deviceId": "dev", "baseCursor": 1,
526			"change": map[string]any{"id": "c3", "payload": map[string]any{"c": 3}},
527		})
528		if w.Code != 200 || body["outcome"] != "merged" || body["cursor"].(float64) != 3 {
529			t.Fatalf("merged = %d %v body=%s", w.Code, body, w.Body.String())
530		}
531	
532		// Stale client posts a payload colliding with later key "b" -> 409 zero write.
533		before, _, _ := s.ListChanges("doc", 0, 100)
534		w, _ = mergeBody(t, h, "doc", map[string]any{
535			"deviceId": "dev", "baseCursor": 0,
536			"change": map[string]any{"id": "c4", "payload": map[string]any{"b": 99}},
537		})
538		if w.Code != http.StatusConflict {
539			t.Fatalf("clash = %d body=%s", w.Code, w.Body.String())
540		}
541		after, _, _ := s.ListChanges("doc", 0, 100)
542		if len(after) != len(before) {
543			t.Fatalf("conflict changed row count: before=%d after=%d", len(before), len(after))
544		}
545	}
