package server

import (
	"net/http"
	"testing"
)

func TestScratchEdge(t *testing.T) {
	h, _ := newTestHandler(t)

	// Bare "sessions" in the deviceId position, unregistered -> 404 (ordinary id).
	if w, _ := doRequest(t, h, http.MethodGet, "/v1/devices/sessions"); w.Code != http.StatusNotFound {
		t.Fatalf("GET /v1/devices/sessions (unregistered) = %d, want 404", w.Code)
	}
	registerDevice(t, h, "sessions")
	createSession(t, h, "sessions", "a")
	if w, items := getSessionList(t, h, "/v1/devices/sessions"); w.Code != http.StatusOK ||
		!equalStrings(sessionIDs(items), []string{"a"}) {
		t.Fatalf("device named sessions list = %d %v", w.Code, items)
	}

	// GET item path (no such list endpoint) -> 400 even for an existing session.
	if w, _ := doRequest(t, h, http.MethodGet, "/v1/devices/sessions/a"); w.Code != http.StatusBadRequest {
		t.Fatalf("GET session item = %d, want 400", w.Code)
	}
	// HEAD on the collection: Go's ServeMux does not auto-route HEAD to the GET
	// pattern when a method-less collection fallback exists; it hits the
	// fallback -> 400.
	if w, _ := doRequest(t, h, http.MethodHead, "/v1/devices/sessions"); w.Code != http.StatusBadRequest {
		t.Fatalf("HEAD collection = %d, want 400", w.Code)
	}
	// Unknown query params are ignored (only limit/offset are interpreted).
	if w, _ := getSessionList(t, h, "/v1/devices/sessions?foo=bar&limit=1"); w.Code != http.StatusOK {
		t.Fatalf("unknown query param = %d, want 200", w.Code)
	}
